---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)
hl.on("hyprland.start", function()
	-- Make the Wayland session environment available to user services.
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("~/.local/bin/caelestia-hyprglass")
	hl.exec_cmd("caelestia shell -d")
	hl.exec_cmd("fcitx5 -d")
	hl.exec_cmd("wl-paste --type text --watch ~/.local/bin/caelestia-cliphist-store")
	hl.exec_cmd("wl-paste --type image --watch ~/.local/bin/caelestia-cliphist-store")
	hl.exec_cmd("nm-applet --indicator")
	hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
end) -------------------------------
