	general = {
		gaps_in = 6,
		gaps_out = 12,

		border_size = 2,

		col = {
			active_border = { colors = { "rgba(ffffffaa)", "rgba(007affaa)" }, angle = 45 },
			inactive_border = "rgba(ffffff33)",
