-- Configure the selected Caelestia backdrop before installing layer rules.
-- hyprglass.lua sets this global even when the plugin is unavailable.
dofile(os.getenv("HOME") .. "/.config/hypr/hyprglass.lua")
local caelestiaGlassBackend = rawget(_G, "caelestiaGlassBackend") or "liquid"
local useLiquidGlass = caelestiaGlassBackend == "liquid"

-- Panel-sized surfaces keep controls and refraction in the same animation.
for panel, direction in pairs({
    ["control-center"] = "bottom",
    dashboard = "top",
    launcher = "bottom",
    quickpanel = "bottom",
    sidebar = "right",
    session = "right",
    osd = "right",
    notifications = "top",
    lyrics = "top",
    popout = "left",
    bar = "left",
    toast = "bottom",
}) do
    hl.layer_rule({
        name = "caelestia-" .. panel,
        match = { namespace = "^caelestia-" .. panel .. "$" },
        blur = not useLiquidGlass,
        ignore_alpha = 0.01,
        animation = "slide " .. direction,
    })
end

-- The drawers root is a transparent compositor surface. Liquid mode keeps
-- native blur disabled; fallback mode lets Hyprland blur it normally.
hl.layer_rule({
    name = "caelestia-drawers-no-blur",
    match = { namespace = "^caelestia-drawers$" },
    blur = not useLiquidGlass,
    blur_popups = not useLiquidGlass,
    ignore_alpha = 0.01,
})

hl.layer_rule({
    name = "caelestia-glass-frame",
    match = { namespace = "^caelestia-frame-(top|bottom|left|right)$" },
    blur = not useLiquidGlass,
    blur_popups = not useLiquidGlass,
    ignore_alpha = 0.01,
    no_anim = true,
})

-- Launchpad intentionally keeps native Gaussian blur in both backends.
hl.layer_rule({
    name = "caelestia-launchpad-gaussian",
    match = { namespace = "^caelestia-launchpad$" },
    blur = true,
    ignore_alpha = 0.01,
    no_anim = true,
})

-- A hover popout should appear locally rather than slide from the output edge.
hl.layer_rule({
    name = "caelestia-popout-fade",
    match = { namespace = "^caelestia-popout$" },
    animation = "fade",
})

for _, tag in ipairs({ "hyprglass_enabled", "hyprglass_preset_caelestia" }) do
    hl.window_rule({
        name = "caelestia-nexus-" .. tag,
        match = { class = "^org.quickshell$", title = "^Nexus .*" },
        tag = "+" .. tag,
    })
end
